// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _target, uint256 _value) public {
        // Bound value to avoid overflow issues
        _value = bound(_value, 0, address(c).balance);

        // Record initial state
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        // Call sendMoney - note: .call{value: ...}("") will forward all gas
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", _target, _value));

        // After call, check depositsCount
        uint256 depositsAfter = c.depositsCount();

        // The rule: depositsCount should either stay the same (if transfer succeeded) 
        // or increase (if transfer failed due to gas, because the receive function in C increments it)
        // Since .transfer() uses fixed 2300 gas, complex receivers will fail and the original .call() would succeed
        // For the reference (.call), failed transfers still increment depositsCount
        // For the mutant (.transfer), failed transfers do NOT increment depositsCount
        // So depositsCount should be >= depositsBefore if the call reverted with .transfer
        bool depositsIncreased = depositsAfter > depositsBefore;
        assertTrue(depositsIncreased || success);
    }
}

